class Solution:
    def makePositive(self, nums: List[int]) -> int:
        n = len(nums)
        ans = 0
        while True:
            p = [0]
            for x in nums: p.append(p[-1] + x)
            bad = -1
            for k in range(3, n + 1):
                if p[k] <= min(p[:k-2]):
                    bad = k
                    break
            if bad < 0:
                return ans
            mi = min(range(bad - 2), key=lambda i: p[i])
            nums[mi] = 10**18
            ans += 1

