class Solution {
public:
    int makePositive(vector<int>& nums) {
        int n = nums.size(), ans = 0;
        while (true) {
            vector<long long> p(n + 1, 0);
            for (int i = 0; i < n; i++) p[i + 1] = p[i] + nums[i];
            int bad = -1;
            for (int k = 3; k <= n && bad < 0; k++) {
                long long mn = LLONG_MAX;
                for (int i = 0; i <= k - 3; i++) mn = min(mn, p[i]);
                if (p[k] <= mn) bad = k;
            }
            if (bad < 0) return ans;
            int mi = 0;
            for (int i = 0; i <= bad - 3; i++) if (p[i] < p[mi]) mi = i;
            nums[mi] = 1000000000000000000LL;
            ans++;
        }
    }
};

