import heapq
class Solution:
    def makePositive(self, nums: List[int]) -> int:
        n = len(nums)
        pre = [0] * (n + 1)
        for i, x in enumerate(nums): pre[i + 1] = pre[i] + x
        heap, used, ans = [], [False] * (n + 1), 0
        for k in range(3, n + 1):
            heapq.heappush(heap, (pre[k - 3], k - 3))
            while used[heap[0][1]]: heapq.heappop(heap)
            v, i = heap[0]
            if pre[k] <= v:
                ans += 1
                used[i] = True
        return ans

