class Solution {
    public int makePositive(int[] nums) {
        int n = nums.length, ans = 0;
        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        boolean[] used = new boolean[n + 1];
        for (int k = 3; k <= n; k++) {
            pq.add(new long[]{pre[k - 3], k - 3});
            while (used[(int) pq.peek()[1]]) pq.poll();
            long[] top = pq.peek();
            if (pre[k] <= top[0]) { ans++; used[(int) top[1]] = true; }
        }
        return ans;
    }
}

