var makePositive = function(nums) {
    const n = nums.length, pre = new Array(n + 1).fill(0n);
    for (let i = 0; i < n; i++) pre[i + 1] = pre[i] + BigInt(nums[i]);
    const heap = [], used = new Array(n + 1).fill(false);
    const push = (v, i) => { heap.push([v, i]); let c = heap.length - 1;
        while (c > 0) { const p = (c - 1) >> 1; if (heap[p][0] <= heap[c][0]) break;
            [heap[p], heap[c]] = [heap[c], heap[p]]; c = p; } };
    const pop = () => { const t = heap[0], l = heap.pop();
        if (heap.length) { heap[0] = l; let c = 0;
            for (;;) { let a = 2*c+1, b = a+1, m = c;
                if (a < heap.length && heap[a][0] < heap[m][0]) m = a;
                if (b < heap.length && heap[b][0] < heap[m][0]) m = b;
                if (m === c) break; [heap[m], heap[c]] = [heap[c], heap[m]]; c = m; } } };
    let ans = 0;
    for (let k = 3; k <= n; k++) {
        push(pre[k - 3], k - 3);
        while (used[heap[0][1]]) pop();
        if (pre[k] <= heap[0][0]) { ans++; used[heap[0][1]] = true; }
    }
    return ans;
};
